(() => {
'use strict';
const icons={audit:'<path d="m3 6 1.5 1.5L7 5M10 6h11M3 12l1.5 1.5L7 11M10 12h11M3 18l1.5 1.5L7 17M10 18h11"/>',selection:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',source:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6m-3-14-2 16"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M15 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h3"/>'};
const svg=k=>'<svg viewBox="0 0 24 24" aria-hidden="true">'+icons[k]+'</svg>';
const byId=id=>document.getElementById(id),kind=document.body.dataset.demo;
let group=document.querySelector('.top-actions');
if(!group){group=document.querySelector('.actions');group.classList.add('top-actions');group.removeAttribute('data-liquid-glass');}
group.classList.add('demo-top-actions');
if(kind==='scale'){
 const info=document.createElement('aside');info.id='demoInfo';info.className='demo-info';info.hidden=true;info.setAttribute('data-liquid-glass','panel');info.innerHTML='<div class="demo-panel-head"><h2>Scale · 来源与前提</h2><button aria-label="关闭来源与前提">×</button></div><p>选择 X、scale 或 bias，核对参数共享与输出关系；修改参数后查看 CPU 参考值。</p><p>依据固定版本的 Python 参考计算；设备 Kernel 访问与性能未在本轮验证。</p><button id="usageOpen">教程</button>';document.body.append(info);info.querySelector('button').onclick=()=>info.hidden=true;
 const b=document.createElement('button');b.id='demoInfoToggle';group.append(b);b.onclick=()=>{info.hidden=!info.hidden;b.setAttribute('aria-expanded',String(!info.hidden))};
}
const entries=kind==='scale'?[['inspect','selection','当前选择'],['source','source','源码与范围'],['demoInfoToggle','info','来源与前提']]:[['auditToggle','audit','自动核查'],['tailDemo','audit','查看尾块差异'],['evidenceToggle','selection','当前选择'],['sourceToggle','source',kind==='rsfa'?'原始数据':'源码'],['infoToggle','info','来源与前提'],['infoButton','info','来源与前提']];
for(const [id,icon,label]of entries){const b=byId(id);if(!b)continue;const badge=b.querySelector('.audit-count');b.innerHTML=svg(icon);if(badge)b.append(badge);b.classList.add('demo-icon');b.setAttribute('data-liquid-glass','icon');b.setAttribute('aria-label',label);b.setAttribute('data-tip',label);group.append(b);}
// One tooltip owner, including controls produced after configuration changes.
const selector='button,a[href],input:not([type="hidden"]),select,textarea,summary,[role="button"],[role="option"],[data-tip]';
const normalize=root=>{if(root.nodeType!==1&&root!==document)return;const all=[...(root.matches?.('[title]')?[root]:[]),...root.querySelectorAll('[title]')];for(const e of all){if(!e.dataset.tip)e.dataset.tip=e.getAttribute('title');e.removeAttribute('title');}};
normalize(document);new MutationObserver(ms=>ms.forEach(m=>{if(m.type==='attributes')normalize(m.target);else m.addedNodes.forEach(normalize)})).observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:['title']});
const tip=document.createElement('div');tip.id='demoHoverTip';tip.role='tooltip';tip.hidden=true;document.body.append(tip);let active;
function hide(){if(active)active.removeAttribute('aria-describedby');active=null;tip.hidden=true;}
function show(target,override){if(!target)return hide();const label=override||target.dataset.tip||target.getAttribute('aria-label')||target.getAttribute('placeholder')||target.closest('label')?.textContent.trim()||target.textContent.trim()||target.id;if(!label)return;hide();active=target;const modal=target.closest('dialog[open]');(modal||document.body).append(tip);tip.textContent=label;tip.hidden=false;target.setAttribute('aria-describedby',tip.id);const b=target.getBoundingClientRect(),r=tip.getBoundingClientRect();tip.style.left=Math.max(8,Math.min(innerWidth-r.width-8,b.left+b.width/2-r.width/2))+'px';tip.style.top=(b.top>r.height+12?b.top-r.height-8:Math.min(innerHeight-r.height-8,b.bottom+8))+'px';}
document.addEventListener('pointerover',e=>{const t=e.target.closest(selector);if(t!==active)show(t)});document.addEventListener('pointerout',e=>{if(active&&!active.contains(e.relatedTarget))hide()});document.addEventListener('focusin',e=>show(e.target.closest(selector)));document.addEventListener('focusout',hide);document.addEventListener('pointermove',e=>{const target=e.target.closest('[role="button"]');const old=byId('tooltip');if(target?.closest('svg')&&old&&!old.hidden&&old.textContent)show(target,old.textContent)});document.addEventListener('pointerdown',hide);window.addEventListener('blur',hide);window.addEventListener('keydown',e=>{if(e.key==='Escape')hide()});
const dialog=byId('usageWindow');if(dialog){const open=byId('usageOpen');if(open){open.textContent='教程';open.dataset.tip='打开教程：价值、使用、扩展与实现分工';open.onclick=()=>dialog.showModal();}byId('usageClose').onclick=()=>dialog.close();dialog.classList.add('demo-tutorial');dialog.querySelectorAll('pre').forEach((pre,i)=>{let block=pre.closest('.prompt-block');if(!block){block=document.createElement('div');block.className='prompt-block';pre.before(block);block.append(pre);}if(!pre.id)pre.id='demo-code-'+i;let b=block.querySelector('button');if(!b){b=document.createElement('button');block.prepend(b);}b.className='prompt-copy';b.innerHTML=svg('copy');b.setAttribute('aria-label','复制代码');b.dataset.tip='复制代码';b.onclick=async()=>{const status=byId('usageCopyStatus');try{await navigator.clipboard.writeText(pre.textContent);if(status)status.textContent='已复制';b.dataset.tip='已复制';}catch{if(status)status.textContent='复制失败，请选择代码后手动复制';b.dataset.tip='复制失败，请手动复制';}if(active===b)show(b);};});}
})();
